from pathlib import Path
import hashlib,json,subprocess

tid='DEV-PRED-AUTOBUILD-PINFIX-20260930-E005'
wt=Path.home()/'.local/share/prediction-project-executor/worktrees'/tid
code='ffffffffffffffffffffffffffffffffffffffff'
if not wt.is_dir():
    code='5000000000000000000000000000000000000001'
else:
    planner=wt/'control/codex_supervisor/build_planner.py'
    config=wt/'knowledge/codex_runtime/CONFIG.json'
    marker='For REQUIRES_SHARED_INFRA or INSUFFICIENT_SPEC, components MUST be an empty list []'
    if not planner.is_file() or marker not in planner.read_text(errors='replace'):
        code='5000000000000000000000000000000000000002'
    elif not config.is_file():
        code='5000000000000000000000000000000000000003'
    else:
        psha=hashlib.sha256(planner.read_bytes()).hexdigest()
        craw=config.read_text(errors='replace')
        pin_updated=(psha in craw)
        cache=wt/'.pytest_cache/v/cache/nodeids'
        last=wt/'.pytest_cache/v/cache/lastfailed'
        node=[]
        if cache.is_file():
            try: node=json.loads(cache.read_text())
            except Exception: node=[]
        lf={}
        if last.is_file():
            try: lf=json.loads(last.read_text())
            except Exception: lf={}
        joined='\n'.join(str(x) for x in node)
        lfj='\n'.join(str(x) for x in lf)
        targeted_seen=('test_build_planner_nonbuildable_components.py' in joined and 'test_build_planner_retry.py' in joined)
        runtime_seen=('test_autobuild_runtime_wiring_e004i.py' in joined)
        full_seen=(len(node) > 100)
        cp=subprocess.run(['git','status','--porcelain=v1'],cwd=wt,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
        status=cp.stdout if cp.returncode==0 else ''
        cp2=subprocess.run(['git','rev-parse','HEAD'],cwd=wt,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
        head=cp2.stdout.strip() if cp2.returncode==0 else ''
        source='57d1aa8b59a31b8b776b264aa3ac663ebc0277c1'
        staged=[]
        cp3=subprocess.run(['git','diff','--cached','--name-only'],cwd=wt,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
        if cp3.returncode==0: staged=[x for x in cp3.stdout.splitlines() if x.strip()]
        if head and head != source:
            code='5000000000000000000000000000000000000009'
        elif staged:
            code='5000000000000000000000000000000000000008'
        elif not pin_updated:
            code='5000000000000000000000000000000000000004'
        elif targeted_seen and ('test_build_planner_nonbuildable_components.py' in lfj or 'test_build_planner_retry.py' in lfj):
            code='5000000000000000000000000000000000000005'
        elif targeted_seen and runtime_seen and 'test_autobuild_runtime_wiring_e004i.py' in lfj:
            code='5000000000000000000000000000000000000006'
        elif full_seen and lf:
            code='5000000000000000000000000000000000000007'
        elif targeted_seen and not runtime_seen:
            code='500000000000000000000000000000000000000a'
        elif runtime_seen and not full_seen:
            code='500000000000000000000000000000000000000b'
        elif full_seen:
            code='500000000000000000000000000000000000000c'
        else:
            code='500000000000000000000000000000000000000d'
print(code)
